meta.example:
import { FileUpload } from "@/components/aeri/file-upload";

<FileUpload
  accept="image/png,image/jpeg"
  files={files}
  maxFileSize={5 * 1024 * 1024}
  maxFiles={3}
  onFileCancel={(file) => cancelUpload(file.id)}
  onFileRetry={(file) => retryUpload(file.id)}
  onFilesSelected={(selectedFiles) => setFiles(createUploadItems(selectedFiles))}
/>
